package aggregates

import "keyloop-coding-challenge/internal/domain"

// Commands carry caller intent. IDs for new entities are generated by the caller so
// the aggregate stays deterministic. The vehicle ID is the aggregate ID.

type StockVehicle struct {
	DealershipID string
	VIN          string
	Make         string
	Model        string
	ModelYear    int
	StockedOn    domain.Date
}

type ProposeAction struct {
	ActionID   string
	ActionType domain.ActionType
	Note       string
}

type ReviseAction struct {
	ActionID   string
	ActionType domain.ActionType
	Note       string
}

type CancelAction struct {
	ActionID string
	Reason   string
}

type SellVehicle struct {
	SoldOn domain.Date
}
